import { describe, expect, it } from "vitest";

import { inboxUrl } from "../src/components/inboxLink";

describe("inboxUrl", () => {
  it("links a valid owner/repo#number to the GitHub issue", () => {
    expect(inboxUrl("grn-inbox/inboxes#123")).toBe(
      "https://github.com/grn-inbox/inboxes/issues/123",
    );
    expect(inboxUrl("a.b_c-d/e.f#1")).toBe(
      "https://github.com/a.b_c-d/e.f/issues/1",
    );
  });

  it.each([
    null,
    "",
    "evil.com/x#1/../",
    "javascript:alert(1)//x/y#1",
    "https://evil.com/x#1",
    "owner/repo",
    "owner/repo#",
    "owner/repo#12a",
    "owner#1",
    "owner/repo/extra#1",
    "owner/repo#1\n",
    "../..#1",
    "owner/..#1",
  ])("ignores %j", (value) => {
    expect(inboxUrl(value)).toBeUndefined();
  });
});
